diff --git a/sql/sql_acl.cc b/sql/sql_acl.cc
index 43aac8d870a0..d1b8f8c5b65e 100644
--- a/sql/sql_acl.cc
+++ b/sql/sql_acl.cc
@@ -69,7 +69,6 @@ bool auth_plugin_is_built_in(const char *plugin_name);
 bool auth_plugin_supports_expiration(const char *plugin_name);
 void optimize_plugin_compare_by_pointer(LEX_STRING *plugin_name);

-
 static const
 TABLE_FIELD_TYPE mysql_db_table_fields[MYSQL_DB_FIELD_COUNT] = {
   {
@@ -588,6 +587,8 @@ class ACL_DB :public ACL_ACCESS


 #ifndef NO_EMBEDDED_ACCESS_CHECKS
+static void validate_user_plugin_records();
+
 static ulong get_sort(uint count,...);
 static bool show_proxy_grants (THD *thd, LEX_USER *user,
                                char *buff, size_t buffsize);
@@ -1422,6 +1423,7 @@ static my_bool acl_load(THD *thd, TABLE_LIST *tables)
   }
   freeze_size(&acl_proxy_users);

+  validate_user_plugin_records();
   init_check_host();

   initialized=1;
@@ -11860,3 +11862,73 @@ int check_password_policy(String *password)
   }
   return (0);
 }
+
+#ifndef NO_EMBEDDED_ACCESS_CHECKS
+my_bool validate_user_plugins= TRUE;
+
+/**
+  Iterate over the user records and check for irregularities.
+  Currently this includes :
+   - checking if the plugin referenced is present.
+   - if there's sha256 users and there's neither SSL nor RSA configured
+*/
+static void
+validate_user_plugin_records()
+{
+  DBUG_ENTER("validate_user_plugin_records");
+  if (!validate_user_plugins)
+    DBUG_VOID_RETURN;
+
+  lock_plugin_data();
+  for (uint i=0 ; i < acl_users.elements ; i++)
+  {
+    struct st_plugin_int *plugin;
+    ACL_USER *acl_user=dynamic_element(&acl_users,i,ACL_USER*);
+
+    if (acl_user->plugin.length)
+    {
+      /* rule 1 : plugin does exit */
+      if (!auth_plugin_is_built_in(acl_user->plugin.str))
+      {
+        plugin= plugin_find_by_type(&acl_user->plugin,
+                                    MYSQL_AUTHENTICATION_PLUGIN);
+
+        if (!plugin)
+        {
+          sql_print_warning("The plugin '%.*s' used to authenticate "
+                            "user '%s'@'%.*s' is not loaded."
+                            " Nobody can currently login using this account.",
+                            (int) acl_user->plugin.length, acl_user->plugin.str,
+                            acl_user->user,
+                            acl_user->host.get_host_len(), 
+                            acl_user->host.get_host());
+        }
+      }
+      if (acl_user->plugin.str == sha256_password_plugin_name.str &&
+#if !defined(HAVE_YASSL)
+          (!g_rsa_keys.get_private_key() || !g_rsa_keys.get_public_key()) &&
+#endif
+          !ssl_acceptor_fd)
+      {
+          sql_print_warning("The plugin '%s' is used to authenticate "
+                            "user '%s'@'%.*s', "
+#if !defined(HAVE_YASSL)
+                            "but neither SSL nor RSA keys are "
+#else
+                            "but no SSL is "
+#endif
+                            "configured. "
+                            "Nobody can currently login using this account.",
+                            sha256_password_plugin_name.str,
+                            acl_user->user,
+                            acl_user->host.get_host_len(), 
+                            acl_user->host.get_host());
+      }
+    }
+  }
+  unlock_plugin_data();
+  DBUG_VOID_RETURN;
+}
+
+#endif // NO_EMBEDDED_ACCESS_CHECKS
+
diff --git a/sql/sql_acl.h b/sql/sql_acl.h
index 59ed6be7ba2b..7d78742c2f10 100644
--- a/sql/sql_acl.h
+++ b/sql/sql_acl.h
@@ -444,4 +444,7 @@ bool acl_check_proxy_grant_access (THD *thd, const char *host, const char *user,
 void init_default_auth_plugin();
 int set_default_auth_plugin(char *, int);

+/** controls the extra checks on plugin availability for mysql.user records */
+extern my_bool validate_user_plugins;
+
 #endif /* SQL_ACL_INCLUDED */
diff --git a/sql/sql_plugin.cc b/sql/sql_plugin.cc
index 9d8fd52d17b6..a210caefb1ca 100644
--- a/sql/sql_plugin.cc
+++ b/sql/sql_plugin.cc
@@ -3776,3 +3776,40 @@ void add_plugin_options(std::vector<my_option> *options, MEM_ROOT *mem_root)
   }
 }

+/** 
+  Searches for a correctly loaded plugin of a particular type by name
+
+  @param plugin   the name of the plugin we're looking for
+  @param type     type of the plugin (0-MYSQL_MAX_PLUGIN_TYPE_NUM)
+  @return plugin, or NULL if not found
+*/
+struct st_plugin_int *plugin_find_by_type(LEX_STRING *plugin, int type)
+{
+  st_plugin_int *ret;
+  DBUG_ENTER("plugin_find_by_type");
+
+  ret= plugin_find_internal(plugin, type);
+  DBUG_RETURN(ret && ret->state == PLUGIN_IS_READY ? ret : NULL);
+}
+
+
+/** 
+  Locks the plugin strucutres so calls to plugin_find_inner can be issued.
+
+  Must be followed by unlock_plugin_data.
+*/
+int lock_plugin_data()
+{
+  DBUG_ENTER("lock_plugin_data");
+  DBUG_RETURN(mysql_mutex_lock(&LOCK_plugin));
+}
+
+
+/** 
+  Unlocks the plugin strucutres as locked by lock_plugin_data()
+*/
+int unlock_plugin_data()
+{
+  DBUG_ENTER("unlock_plugin_data");
+  DBUG_RETURN(mysql_mutex_unlock(&LOCK_plugin));
+}
diff --git a/sql/sql_plugin.h b/sql/sql_plugin.h
index 40a86e8844bc..5ebd133ac51d 100644
--- a/sql/sql_plugin.h
+++ b/sql/sql_plugin.h
@@ -168,4 +168,9 @@ typedef my_bool (plugin_foreach_func)(THD *thd,
 #define plugin_foreach(A,B,C,D) plugin_foreach_with_mask(A,B,C,PLUGIN_IS_READY,D)
 extern bool plugin_foreach_with_mask(THD *thd, plugin_foreach_func *func,
                                      int type, uint state_mask, void *arg);
+
+/* interface to randomly access plugin data */
+struct st_plugin_int *plugin_find_by_type(LEX_STRING *plugin, int type);
+int lock_plugin_data();
+int unlock_plugin_data();
 #endif
